const cats=[['🍔 HAMBÚRGUERES',[['POPEYE X-BURGER',24.99,'Pão de brioche, hambúrguer artesanal de 140g, queijo cheddar, maionese e ketchup.',"IMG3"],['POPEYE SMASH',37.99,'Pão de brioche, 2 carnes smash de 140g cada, queijo cheddar, bacon e geleia de cebola.',"IMG6"],['POPEYE X-SALADA',32.99,'Pão de brioche, 2 carnes, queijo cheddar, bacon, ovo, alface, tomate, cebola roxa, barbecue e maionese verde.',"IMG4"],['POPEYE TITÃ BURGER',44.99,'Pão de brioche, 2 carnes, queijo cheddar, bacon, cebola roxa, tomate, picles e maionese de churrasco.',"IMG2"],['POPEYE DUPLO BACON',34.99,'Pão de brioche, 2 carnes de 140g cada, queijo cheddar, bacon, cebola roxa e barbecue.',"IMG1"],['POPEYE ONION RINGS',44.99,'Pão de brioche, 2 carnes de 140g cada, queijo cheddar, duplo bacon, onion rings, cebola roxa e barbecue.',"IMG0"],['POPEYE FRANGO CROCANTE',39.90,'Pão de brioche, frango empanado crocante, queijo cheddar, bacon, alface, tomate e maionese.',"IMG5"]]],['🍟 PORÇÕES',[['BATATA FRITA',6.99,'Batata sequinha e crocante.',"IMG7"],['BATATA CHEDDAR BACON',15.00,'Batata crocante com creme de cheddar e bacon em cubos.',"IMG8"]]],['🥤 BEBIDAS',[['COCA-COLA 350 ML',7.99,'Coca-Cola gelada 350 ml.',"IMG9"],['GUARANÁ ANTARCTICA 350 ML',7.99,'Guaraná Antarctica gelado 350 ml.',"IMG9"]]]];const DATA0='data:image/jpeg;base64,';const DATA1='data:image/jpeg;base64,';const DATA2='data:image/jpeg;base64,';const DATA3='data:image/jpeg;base64,';const DATA4='data:image/jpeg;base64,';const DATA5='data:image/jpeg;base64,';const DATA6='data:image/jpeg;base64,';const DATA7='data:image/jpeg;base64,';const DATA8='data:image/jpeg;base64,';const DATA9='data:image/jpeg;base64,';const DATA10='data:image/jpeg;base64,';const extras=[["Hambúrguer extra",8],["Cheddar extra",4],["Bacon",5],["Onion rings",6],["Cebola caramelizada",3],["Molho especial",2]],rem=["Alface","Tomate","Cebola","Molho especial"];let chosen,cart=[];const money=x=>x.toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
function render(){catsEl.innerHTML=cats.map((c,i)=>`<button class="cat ${i?"":"active"}" onclick="show(${i},this)">${c[0]}</button>`).join("");content.innerHTML=cats.map((c,ci)=>`<section id="s${ci}"><h2 class="title">${c[0]}</h2><div class="grid">${c[1].map((p,pi)=>`<article class="card"><div class="pic">${p[3].startsWith("IMG")?`<img src="${[DATA0,DATA1,DATA2,DATA3,DATA4,DATA5,DATA6,DATA7,DATA8,DATA9][+p[3].slice(3)]}">`:p[3]}</div><div class="body"><h3>${p[0]}</h3><div class="price">${money(p[1])}</div><div class="desc">${p[2]}</div><button class="add" onclick="openM(${ci},${pi})">+ Adicionar</button></div></article>`).join("")}</div></section>`).join("")}
function show(i,b){document.querySelectorAll(".cat").forEach(x=>x.classList.remove("active"));b.classList.add("active");document.getElementById("s"+i).scrollIntoView({behavior:"smooth"})}
function openM(c,p){chosen=cats[c][1][p];pt.textContent=chosen[0];extrasEl.innerHTML=extras.map((e,i)=>`<label class="extra">${e[0]} +${money(e[1])}<input type="checkbox" value="${i}"></label>`).join("");remEl.innerHTML=rem.map((r,i)=>`<label class="extra">${r}<input type="checkbox" value="${i}"></label>`).join("");iobs.value="";modal.classList.add("show")}
function closeM(){modal.classList.remove("show")}
function add(){let e=[...extrasEl.querySelectorAll("input:checked")].map(x=>extras[x.value]),r=[...remEl.querySelectorAll("input:checked")].map(x=>rem[x.value]);cart.push({name:chosen[0],price:chosen[1]+e.reduce((s,x)=>s+x[1],0),extras:e.map(x=>x[0]),rem:r,obs:iobs.value,q:1});closeM();renderCart();toggleCart(true)}
function renderCart(){let t=0,n=0;items.innerHTML=cart.map((x,i)=>{t+=x.price*x.q;n+=x.q;return `<div class="item"><b>${x.q}x ${x.name}</b><br><small>${[...x.extras,...x.rem.map(r=>"sem "+r),x.obs?"Obs.: "+x.obs:""].filter(Boolean).join(", ")}</small><br>${money(x.price*x.q)}<div class="qty"><button onclick="qty(${i},-1)">−</button>${x.q}<button onclick="qty(${i},1)">+</button><button onclick="del(${i})">🗑️</button></div></div>`}).join("")||"<p style='text-align:center;color:#777'>Seu carrinho está vazio 🍔</p>";total.textContent=money(t);count.textContent=n}
function qty(i,d){cart[i].q+=d;if(cart[i].q<1)cart.splice(i,1);renderCart()}function del(i){cart.splice(i,1);renderCart()}function toggleCart(v){panel.classList.toggle("open",v===true?true:undefined)}
function checkout(){if(!cart.length)return alert("Adicione produtos ao carrinho.");order.classList.add("show")}
function closeO(){order.classList.remove("show")}
document.querySelectorAll('input[name="recv"]').forEach(x=>x.onchange=()=>df.style.display=x.value==="Delivery"&&x.checked?"block":"none");
function send(){let nm=name.value.trim(),rv=document.querySelector('input[name="recv"]:checked').value,py=document.querySelector('input[name="pay"]:checked').value;if(!nm)return alert("Informe seu nome.");if(rv==="Delivery"&&!addr.value.trim())return alert("Informe o endereço.");let t=cart.reduce((s,x)=>s+x.price*x.q,0),m=`🍔 *NOVO PEDIDO - POPEYE BURGERS*\n\n👤 *Cliente:* ${nm}\n📦 *Recebimento:* ${rv}\n`;if(rv==="Delivery")m+=`📍 *Endereço:* ${addr.value}\n🧭 *Referência:* ${ref.value}\n`;m+=`💳 *Pagamento:* ${py}\n\n*ITENS:*\n`;cart.forEach(x=>m+=`• ${x.q}x ${x.name} — ${money(x.price*x.q)}\n`);if(oobs.value)m+=`\n📝 ${oobs.value}\n`;m+=`\n💰 *TOTAL: ${money(t)}*`;window.open("https://wa.me/5511981877566?text="+encodeURIComponent(m),"_blank");closeO()}
const catsEl=document.getElementById("cats"),content=document.getElementById("content"),items=document.getElementById("items"),total=document.getElementById("total"),count=document.getElementById("count"),panel=document.getElementById("panel"),modal=document.getElementById("modal"),order=document.getElementById("order"),pt=document.getElementById("pt"),extrasEl=document.getElementById("extras"),remEl=document.getElementById("rem"),iobs=document.getElementById("iobs"),df=document.getElementById("df"),name=document.getElementById("name"),addr=document.getElementById("addr"),ref=document.getElementById("ref"),oobs=document.getElementById("oobs");;render();renderCart();

